<?php
namespace App\Http\Controllers\Api; use App\Models\{AuditLog,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class AuthController extends ApiController { public function login(Request $r){$data=$r->validate(['login'=>'required|string','password'=>'required|string','device_name'=>'nullable|string|max:100']);$u=User::where('mobile',$data['login'])->orWhere('username',$data['login'])->first();if(!$u||!$u->active||!Hash::check($data['password'],$u->password))return $this->fail('اطلاعات ورود صحیح نیست.',[],401);$token=$u->createToken($data['device_name']??'Android app')->plainTextToken;$this->audit($r,$u,'login');return $this->ok(['token'=>$token,'user'=>$this->user($u)],'ورود با موفقیت انجام شد.');} public function logout(Request $r){$r->user()->currentAccessToken()->delete();$this->audit($r,$r->user(),'logout');return $this->ok(null,'خروج انجام شد.');}public function me(Request $r){return $this->ok($this->user($r->user()));} private function user(User $u){return ['id'=>$u->id,'name'=>$u->name,'mobile'=>$u->mobile,'roles'=>$u->getRoleNames()];}private function audit(Request $r,User $u,string $a):void{AuditLog::create(['user_id'=>$u->id,'action'=>$a,'ip_address'=>$r->ip(),'device_info'=>$r->attributes->get('device_info'),'created_at'=>now()]);}}
